import{_ as e,c as r,o as i,ag as l}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"服務條款","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/terms.md","filePath":"zh-TW/guide/terms.md","lastUpdated":1794112334000}'),t={name:"zh-TW/guide/terms.md"};function h(o,a,n,s,d,c){return i(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="服務條款" tabindex="-1">服務條款 <a class="header-anchor" href="#服務條款" aria-label="Permalink to &quot;服務條款&quot;">​</a></h1><h2 id="條款的接受" tabindex="-1">條款的接受 <a class="header-anchor" href="#條款的接受" aria-label="Permalink to &quot;條款的接受&quot;">​</a></h2><p>下載、安裝或使用 Nicasa（下稱「本應用程式」），即表示你同意受本服務條款（下稱「條款」）拘束。如果你不同意本條款，請勿使用本應用程式。</p><h2 id="服務說明" tabindex="-1">服務說明 <a class="header-anchor" href="#服務說明" aria-label="Permalink to &quot;服務說明&quot;">​</a></h2><p>Nicasa 是一款 macOS 桌面圖片檢視與截圖工具，提供：</p><ul><li>圖片檢視與瀏覽功能</li><li>截圖與螢幕擷取功能</li><li>AI 驅動的影像編輯工具</li><li>用於擷取網頁圖片的 Chrome 瀏覽器擴充功能</li><li>面向設計工作的透明懸浮模式</li></ul><h2 id="授權與使用權利" tabindex="-1">授權與使用權利 <a class="header-anchor" href="#授權與使用權利" aria-label="Permalink to &quot;授權與使用權利&quot;">​</a></h2><h3 id="mac-app-store-版本" tabindex="-1">Mac App Store 版本 <a class="header-anchor" href="#mac-app-store-版本" aria-label="Permalink to &quot;Mac App Store 版本&quot;">​</a></h3><ul><li>需一次性支付 $4.99</li><li>授權在與你的 Apple ID 關聯的裝置上使用</li><li>支援家人共享</li></ul><h3 id="chrome-擴充功能" tabindex="-1">Chrome 擴充功能 <a class="header-anchor" href="#chrome-擴充功能" aria-label="Permalink to &quot;Chrome 擴充功能&quot;">​</a></h3><ul><li>可免費下載與使用</li><li>受 Chrome 線上應用程式商店條款拘束</li></ul><h2 id="使用者責任" tabindex="-1">使用者責任 <a class="header-anchor" href="#使用者責任" aria-label="Permalink to &quot;使用者責任&quot;">​</a></h2><p>你同意：</p><ul><li>僅為合法目的使用本應用程式</li><li>不嘗試對本應用程式進行逆向工程、反編譯或修改</li><li>尊重智慧財產權</li><li>為實現應用程式功能而授予必要的系統權限</li><li>不利用本應用程式違反任何法律或法規</li></ul><h2 id="隱私權與資料" tabindex="-1">隱私權與資料 <a class="header-anchor" href="#隱私權與資料" aria-label="Permalink to &quot;隱私權與資料&quot;">​</a></h2><p>關於資料蒐集與隱私權實務，請參閱我們的<a href="/zh-TW/guide/privacy.html">隱私權政策</a>。</p><h2 id="免責聲明" tabindex="-1">免責聲明 <a class="header-anchor" href="#免責聲明" aria-label="Permalink to &quot;免責聲明&quot;">​</a></h2><h3 id="不提供擔保" tabindex="-1">不提供擔保 <a class="header-anchor" href="#不提供擔保" aria-label="Permalink to &quot;不提供擔保&quot;">​</a></h3><p>本應用程式依「現狀」提供，不附帶任何形式的擔保。開發者否認一切明示或默示的擔保，包括但不限於適售性與特定用途適用性。</p><h3 id="責任限制" tabindex="-1">責任限制 <a class="header-anchor" href="#責任限制" aria-label="Permalink to &quot;責任限制&quot;">​</a></h3><p>在任何情況下，開發者均不對因使用本應用程式而產生的任何間接、附隨、特殊、後果性或懲罰性損害負責。</p><h2 id="智慧財產權" tabindex="-1">智慧財產權 <a class="header-anchor" href="#智慧財產權" aria-label="Permalink to &quot;智慧財產權&quot;">​</a></h2><p>Nicasa 及其相關商標歸開發者所有。本應用程式的程式碼與設計受著作權法保護。</p><h2 id="終止" tabindex="-1">終止 <a class="header-anchor" href="#終止" aria-label="Permalink to &quot;終止&quot;">​</a></h2><p>本條款在終止前持續有效。如果你未能遵守本條款中的任何一條，你依本條款享有的權利將自動終止。</p><h2 id="準據法" tabindex="-1">準據法 <a class="header-anchor" href="#準據法" aria-label="Permalink to &quot;準據法&quot;">​</a></h2><p>本條款受相關司法管轄區的法律管轄並據此解釋，不適用法律衝突原則。</p><h2 id="條款變更" tabindex="-1">條款變更 <a class="header-anchor" href="#條款變更" aria-label="Permalink to &quot;條款變更&quot;">​</a></h2><p>開發者保留隨時修改本條款的權利。變更後繼續使用本應用程式即視為接受新的條款。</p><h2 id="聯絡資訊" tabindex="-1">聯絡資訊 <a class="header-anchor" href="#聯絡資訊" aria-label="Permalink to &quot;聯絡資訊&quot;">​</a></h2><p>如對本條款有疑問，請透過 <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub 儲存庫</a>聯絡我們。</p><p><em>最後更新：2026 年 4 月 16 日</em></p>',32)])])}const m=e(t,[["render",h]]);export{p as __pageData,m as default};
